mapper.select:
select c.id,c.content,c.user_id,c.created_time,c.parent_id,c.like_count, u.username,u.avatar,c.reply_count as childCount from comment c left join user u on c.user_id = u.id where c.target_id = #{targetId}
and c.id < #{lastId}
and c.status = 1 and c.parent_id=0 order by c.created_time desc limit #{size}

select c.id,c.content,c.user_id,c.created_time,c.parent_id,c.like_count, u.username,u.avatar,c.reply_to_user_id as replyUserId, ru.username as replyUsername from comment c left join user u on c.user_id = u.id left join user ru on c.reply_to_user_id = ru.id where c.parent_id = #{targetId}
and c.id < #{lastId}
and c.status = 1 order by c.created_time desc limit #{size}

update.if:
update music
set comment_count = comment_count -#{count}
where id = #{targetId}

